packer {
  required_plugins {
    amazon  = { source = "github.com/hashicorp/amazon", version = ">= 1.3.0" }
    ansible = { source = "github.com/hashicorp/ansible", version = ">= 1.1.0" }
  }
}

variable "base_ami" { type = string }   # pinned, verified vendor image ID
variable "build_id" { type = string }   # CI pipeline run number

source "amazon-ebs" "web" {
  region        = "us-east-1"
  instance_type = "t3.small"
  source_ami    = var.base_ami
  ssh_username  = "ec2-user"
  ami_name      = "golden-rhel9-web-${var.build_id}"
  encrypt_boot  = true
  imds_support  = "v2.0"                # instances launched from this AMI require IMDSv2
  tags = { Baseline = "CIS-RHEL9-L1", BuildId = var.build_id }
}

build {
  sources = ["source.amazon-ebs.web"]

  provisioner "shell" {                 # 1. patch and minimize
    inline = ["sudo dnf -y upgrade", "sudo dnf -y remove telnet tftp rsh ypbind"]
  }

  provisioner "ansible" {               # 2. apply the hardening baseline
    playbook_file = "playbooks/cis-rhel9-level1.yml"
  }

  provisioner "shell" {                 # 3. measure compliance (exit code 2 = some rules failed)
    inline = ["sudo oscap xccdf eval --profile xccdf_org.ssgproject.content_profile_cis_server_l1 --results /tmp/oscap.xml /usr/share/xml/scap/ssg/content/ssg-rhel9-ds.xml || [ $? -eq 2 ]"]
  }

  provisioner "file" {                  # 4. keep the evidence for the CI quality gate
    direction   = "download"
    source      = "/tmp/oscap.xml"
    destination = "reports/oscap-${var.build_id}.xml"
  }

  provisioner "shell" {                 # 5. generalize: no build keys, host keys or IDs
    inline = [
      "sudo rm -f /etc/ssh/ssh_host_* /home/ec2-user/.ssh/authorized_keys /tmp/oscap.xml",
      "sudo truncate -s 0 /etc/machine-id",
      "sudo cloud-init clean --logs"
    ]
  }
}

